package io.fireflysoftware.domain.organization.web.owner;
import io.fireflysoftware.domain.organization.core.owner.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import org.springframework.test.web.reactive.server.WebTestClient;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import reactor.core.publisher.Mono;import java.util.*;import java.util.concurrent.atomic.*;
class CurrentBankOwnerControllerTest {
 final UUID tenant=UUID.randomUUID(),bank=UUID.randomUUID(),enrollment=UUID.randomUUID();
 String path(){return "/api/v1/organization/tenants/"+tenant+"/banks/"+bank+"/enrollments/"+enrollment+"/versions/1/current";}
 @Test void realWebFluxMappingReturnsNoStoreExactAdministrativeSummary(){var calls=new AtomicInteger();var client=WebTestClient.bindToController(new CurrentBankOwnerController((q,limit)->{calls.incrementAndGet();assertEquals(tenant,q.tenantId());assertEquals(bank,q.bankId());assertEquals(enrollment,q.enrollmentId());assertEquals(1,q.version());return Mono.just(new CurrentBankOwnerView(tenant,bank,enrollment,1,UUID.randomUUID(),UUID.randomUUID(),Set.of("ACCOUNTING_BOOK"),1,1,1,1,1000,1000));})).build();client.get().uri(path()).exchange().expectStatus().isOk().expectHeader().cacheControl(CacheControl.noStore()).expectBody().consumeWith(response->{try{var body=new com.fasterxml.jackson.databind.ObjectMapper().readTree(response.getResponseBody());assertEquals(tenant.toString(),body.get("tenantId").asText());assertFalse(body.has("financialAdmission"));}catch(java.io.IOException error){throw new AssertionError(error);}});assertEquals(1,calls.get());}
 @Test void nativeSuspensionRemains409WithoutSummary(){var client=WebTestClient.bindToController(new CurrentBankOwnerController((q,limit)->Mono.error(new ResponseStatusException(HttpStatus.CONFLICT)))).build();client.get().uri(path()).exchange().expectStatus().isEqualTo(409);}
 @Test void malformedRevisionCannotInvokeService(){var calls=new AtomicInteger();var client=WebTestClient.bindToController(new CurrentBankOwnerController((q,limit)->{calls.incrementAndGet();return Mono.empty();})).build();client.get().uri(path().replace("/versions/1/","/versions/not-a-number/")).exchange().expectStatus().isBadRequest();assertEquals(0,calls.get());}
 @Test void defaultOffConfigurationDoesNotConstructCurrentOwnerService(){try(var context=new org.springframework.context.annotation.AnnotationConfigApplicationContext()){context.register(CurrentBankOwnerConfiguration.class);context.refresh();assertTrue(context.getBeansOfType(CurrentBankOwnerReadService.class).isEmpty());}}
 @Test void nonpositiveRevisionIsBadRequestBeforeService(){var calls=new AtomicInteger();var client=WebTestClient.bindToController(new CurrentBankOwnerController((q,limit)->{calls.incrementAndGet();return Mono.empty();})).build();client.get().uri(path().replace("/versions/1/","/versions/0/")).exchange().expectStatus().isBadRequest();assertEquals(0,calls.get());}
 @Test void deadlineHeaderOnlySuppliesAnEarlierTechnicalLimit(){var expected=java.time.Instant.parse("2026-10-27T12:00:00Z");var seen=new AtomicReference<java.time.Instant>();var client=WebTestClient.bindToController(new CurrentBankOwnerController((q,limit)->{seen.set(limit);return Mono.error(new ResponseStatusException(HttpStatus.CONFLICT));})).build();client.get().uri(path()).header("X-Firefly-Operation-Deadline",Long.toString(expected.toEpochMilli())).exchange().expectStatus().isEqualTo(409);assertEquals(expected,seen.get());}
 @Test void successfulSdkResponseIsExplicitWhenErrorResponsesAreDeclared() throws Exception {var method=CurrentBankOwnerController.class.getMethod("current",UUID.class,UUID.class,UUID.class,long.class,Long.class);var responses=method.getAnnotation(io.swagger.v3.oas.annotations.responses.ApiResponses.class).value();var codes=java.util.Arrays.stream(responses).map(io.swagger.v3.oas.annotations.responses.ApiResponse::responseCode).collect(java.util.stream.Collectors.toSet());assertEquals(Set.of("200","400","403","409","503"),codes);var success=java.util.Arrays.stream(responses).filter(r->r.responseCode().equals("200")).findFirst().orElseThrow();assertEquals(1,success.content().length);assertEquals("application/json",success.content()[0].mediaType());assertEquals(CurrentBankOwnerView.class,success.content()[0].schema().implementation());}
}
